from render_theme import *
DRAW={}
def D15(r):
    r.panel('A');x=r.read('functional/nested_universe_membership.tsv.gz');q=x.groupby(['species','contrast'])[['in_G0','in_G1_nested','in_G2']].sum().reindex(CTX)
    f=pd.DataFrame({'G0 only':q.in_G0-q.in_G1_nested,'G1 only':q.in_G1_nested-q.in_G2,'G2':q.in_G2});f.index=[context(*v) for v in f.index];ax=r.bars(0,f,'Nested gene background',colorset=[GREY,BLUE,ORANGE],pad=(16,7,2,10));ax.text(0,1.04,'G0 eligible · G1 measurable · G2 recurrent',transform=ax.transAxes,fontsize=7);r.record('strict-nested-gene-counts',q)
    x=pd.concat([r.read('functional/go_ladder.tsv.gz'),r.read('functional/kegg_ladder.tsv.gz')]);f=x[x.model.eq('L3_full')];hits=f[f.q_database_model.lt(.05)];q=hits.groupby(['comparison','database']).size().unstack(fill_value=0).reindex(index=['G1_vs_G0','G2_vs_G0','G2_vs_G1'],columns=['GO','KEGG'],fill_value=0);q.index=['G1/G0','G2/G0','G2/G1'];r.bars(1,q,'q < .05 test positions');r.note('Counts retain the database×model correction and distinguish measurement and recurrence backgrounds; linked tables contain the full test grid.')
    r.panel('B');q=r.read('prepared:E17-endpoint-14-term-positions.tsv').sort_values(['species','contrast','database','term_name']);labels=[wrap(a.term_name,67) for a in q.itertuples()];heights=np.array([3.3*(lab.count('\n')+1)+1.3 for lab in labels]);yy=np.cumsum(heights)-heights/2
    p=r.pdefs[r.active];comp=p['components'][0];x0,y0,w,hh=comp['rectangle_mm'];p['components']=[copy.deepcopy(comp),copy.deepcopy(comp)];p['components'][0]['rectangle_mm']=[1.5,y0,113,hh];p['components'][1]['rectangle_mm']=[118,y0,40.5,hh]
    ax=r.ax(0,labels=labels,kind='point_interval',pad=(70,10,2,11));right=r.ax(1,kind='point_interval',pad=(2,10,15,11));keys=list(q[['species','contrast']].drop_duplicates().itertuples(index=False,name=None))
    for i,(y,a) in enumerate(zip(yy,q.itertuples())):
        col=PAL[keys.index((a.species,a.contrast))]
        if i%2==0:
            for aa in [ax,right]:aa.axhspan(y-heights[i]/2,y+heights[i]/2,color='#F2F4F5',zorder=-3)
        ax.hlines(y,a.expected,a.hits,color=col,lw=.85);ax.scatter(a.expected,y,s=15,facecolor='white',edgecolor=col,lw=.7,marker='s' if a.database=='KEGG' else 'o');ax.scatter(a.hits,y,s=15,c=col,marker='s' if a.database=='KEGG' else 'o')
        right.plot([1,a.matched_fold],[y,y],color=col,lw=1);right.scatter(a.matched_fold,y,s=15,c=col,marker='s' if a.database=='KEGG' else 'o');right.text(1.13,y,f'{a.q_database_model:.2g}',transform=right.get_yaxis_transform(),va='center',fontsize=7)
    ax.set(yticks=yy,yticklabels=labels,ylim=(heights.sum(),0),xlabel='Expected → observed genes');ax.tick_params(axis='y',labelsize=8);right.set(yticks=yy,ylim=(heights.sum(),0),xlim=(.95,2.15),xticks=[1,1.5,2],xlabel='Matched O/E');right.axvline(1,color=GREY,ls=':',lw=.6);right.text(1.13,1.04,'q',transform=right.transAxes,fontsize=8)
    legend(ax,handles=[Line2D([],[],c=PAL[i],marker='o',ls='',label=context(*key)) for i,key in enumerate(keys)],loc='lower right',bbox_to_anchor=(1,1.025),ncol=2)
    ax.text(0,1.04,'G1/G0 · measurable / eligible',transform=ax.transAxes,fontsize=7);right.text(.0,1.08,'○ GO  □ KEGG',transform=right.transAxes,fontsize=7)
    r.share_y([ax,right],f'{len(q)} selected term × context positions, identical row spacing');r.record('all-14-positive-positions',q)
    r.note('Full term names for the frozen display-selection table; full tests are linked. Left open=matched expected, filled=observed; right matched O/E uses matched_fold, not hypergeometric fold_enrichment. q uses the original database×model family. Circle GO/square KEGG; color identifies the species×contrast cohort. The comparison column records the background for every displayed position. Segments connect counts or a fold to1, not confidence bounds.')
    r.panel('C');m=r.read('functional/functional_mobility.tsv');r.ecdf(0,[(model,z.expected_changed_fraction) for model,z in m.groupby('model')],xlabel='Expected changed-label fraction');p=r.read('functional/functional_power.tsv.gz');p=p[p.model.eq('L3_full')];ax=r.ax(1,kind='line')
    for (db,th),g in p.groupby(['database','threshold']):
        z=g.groupby('odds_ratio').rejection_probability.quantile([.25,.5,.75]).unstack();ax.plot(z.index,z[.5],color=BLUE if db=='GO' else ORANGE,ls='-' if th=='nominal' else '--',label=db+' '+('nom.' if th=='nominal' else 'corrected'));ax.fill_between(z.index,z[.25],z[.75],color=BLUE if db=='GO' else ORANGE,alpha=.08)
    ax.set(xlabel='Injected odds ratio',ylabel='Detection probability',ylim=(0,1));legend(ax,loc='best',ncol=2);r.record('complete-L3-power',p);r.note('Power curves show median/IQR across original conditional term×background simulations; no new test is fitted.')
def D16(r):
    r.panel('A');x=r.read('cross_overlap/overlap_null_results.tsv');models=['joint_measurement_PAS','independent_q5_reference_capacity','independent_range10_reference_capacity'];q=x.copy();q['_row']=[['PS','PM'].index(a.contrast)*3+models.index(a.model) for a in q.itertuples()];r.dots(0,q,'observed',[co+' '+mo for co in ['P–S','P–M'] for mo in ['Joint','Capacity Q5','Capacity R10']],lo='null_q025',hi='null_q975',q='q_within_model_two_contrasts',xlabel='Shared proximal candidates');r.note('Markers observed; bars original null 95% ranges. Filled markers indicate q < .05 within each named two-contrast correction family. J, Q5 and R10 cannot be substituted for each other.')
    x=r.read('cross_sharing/sharing_summary.tsv');q=x[x.metric.eq('WPP')&x.threshold.eq(.02)&x.test.eq('same_direction')].copy();q['label']=q.human_study.map(short)+'×'+q.mouse_study.map(short);r.bars(1,pd.DataFrame({'Observed':q.observed.to_numpy()},index=q.label),'Same-direction genes');r.record('all-direction-sharing-families',x)
    r.panel('B');x=r.read('prepared:E10-continuous-primary-gene-pairs.tsv.gz');ax=r.ax(0,kind='scatter')
    for j,(st,g) in enumerate(x.groupby('state')):ax.scatter(g.human_effect,g.mouse_effect,s=1.7,c=STATE[st],alpha=.12,lw=0,rasterized=True,label=st+'−S')
    zeros(ax,True);ax.set(xlabel='Human observed-state ΔDWUI',ylabel='Mouse observed-state ΔDWUI');legend(ax,handles=[Line2D([],[],ls='',marker='o',ms=3,color=STATE[st],label=st+'−S') for st in sorted(x.state.unique())],loc='best');r.record('all-continuous-gene-pairs',x)
    q=r.read('cross_continuous/continuous_pair_summary.tsv');q=q[q.layer.eq('supported50')&q.state.isin(list('REP'))].sort_values(['state','human','mouse']).copy();q['_row']=range(len(q));r.dots(1,q,'rho',[a.state+' '+a.human+'×'+a.mouse for a in q.itertuples()],lo='lo',hi='hi',xlabel='Gene-pair Spearman ρ');r.note('Sixteen measured study×state pairs, retaining gene-resampling intervals and all available points. Unmeasured state combinations are absent designs, not zero correlations. Codes H1 Xing/H2 Liu/H3 Guan/H4 Panariello, C CIP/W WOT.')
    r.panel('C');a=r.read('hyp:D_direction/direction_contrast_tests.tsv');b=r.read('hyp:D_direction/original_pair_direction_sensitivity.tsv');r.ecdf(0,[(f'Synchronized · {len(a)}',a.q_complete_80),(f'Pair-specific · {len(b)}',b.q_complete_80)],xlabel='Direction-difference q80');r.record('synchronized-direction-difference',a);r.record('pair-specific-direction-difference',b);r.note('The 80-test v2-only family compares distal versus proximal excess. It comprises 48 synchronized and 32 pair-specific tests; sharing-enrichment p values belong to different families.')
    x=r.read('cross_controls/cross_species_power.tsv');q=x[x.experiment.eq('conditional_injection')&x.alpha.eq(.05)&x.tested_model.isin(['L1_capacity','L3_full'])];ax=r.ax(1,kind='line')
    for (co,mod),g in q.groupby(['contrast','tested_model']):ax.plot(g.odds_ratio,g.rejection_rate,color=BLUE if co=='PS' else ORANGE,ls='--' if mod=='L1_capacity' else '-',marker='o',ms=2,label=co+' '+('capacity' if mod=='L1_capacity' else 'full'))
    ax.set(xlabel='Injected odds ratio',ylabel='Detection probability',ylim=(0,1));legend(ax,loc='lower right',ncol=1);r.record('conditional-cross-species-power',q);r.record('direction-null-mobility',r.read('hyp:D_direction/joint_null_mobility.tsv'))
DRAW.update(D15=D15,D16=D16)
